# Verify my understanding - background becomes 0, foreground becomes old background color
def transform_rule2(grid):
    # 5 is foreground, becomes 2 (the old background color in demo)
    # 4 is background, becomes 0 (like the demo's 2→0)
    result = []
    for row in grid:
        new_row = []
        for cell in row:
            if cell == 5:
                new_row.append(2)  # foreground → old background
            elif cell == 4:
                new_row.append(0)  # background → 0
            else:
                new_row.append(cell)
        result.append(new_row)
    return result

